import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
        except StopIteration:
            break

        matrix = []
        for _ in range(n):
            matrix.append(next(iterator))

        possible = True

        for r in range(n):
            for c in range(n):
                if matrix[r][c] == '1':
                    if r + 1 < n and matrix[r+1][c] == '1':
                        possible = False
                        break
                    if c + 1 < n and matrix[r][c+1] == '1':
                        possible = False
                        break
            if not possible:
                break

        if possible:
            results.append("YES")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
